# Shared iSSF-based movement simulator (used by final connectivity and LOIO).
# The caller must source R/00_config.R and R/10_issf_common.R first.
# No graphical output is generated by this module.

simulation_horizons <- list(
  Mating=c(378L, 756L, 1512L),
  Hyperphagia=c(355L, 710L, 1420L)
)
simulation_env_files <- c(
  ELE="ELE_100m_whole.tif", VRM="VRM_100m_whole.tif",
  PBUD="PBUD_L_100m_whole.tif", PDBF="PDBF_L_100m_whole.tif",
  DistMainR="DistMainR_100m_whole.tif",
  DistMinorR="DistMinorR_100m_whole.tif",
  DistEdgeAbs="DistEdgeAbs_L_100m_whole.tif"
)

read_sim_environment <- function(path=sim_env_dir) {
  files <- file.path(path, simulation_env_files)
  names(files) <- names(simulation_env_files)
  missing <- files[!file.exists(files)]
  if (length(missing)) stop("Missing simulation environmental rasters: ", paste(missing, collapse=", "))
  rasters <- lapply(files, terra::rast)
  template <- rasters[[1]]
  for (nm in names(rasters)) {
    if (!terra::compareGeom(template, rasters[[nm]], stopOnError=FALSE)) {
      stop("Environmental geometry mismatch: ", nm)
    }
  }
  if (any(abs(terra::res(template) - 100) > 1e-6)) stop("Expected 100-m rasters.")
  if (!terra::is.lonlat(template) && prod(terra::res(template)) != 10000) {
    stop("Expected projected 100-m environment.")
  }
  # Raster cells are cached once; repeated terra::extract inside trajectories is too slow.
  values <- lapply(rasters, function(r) as.numeric(terra::values(r, mat=FALSE)))
  if (any(vapply(values, length, integer(1)) != terra::ncell(template))) {
    stop("Invalid raster cache length.")
  }
  list(template=template, values=values)
}

read_issf_scaling <- function(path=issf_scaling_file) {
  if (!file.exists(path)) stop("Missing 10-m reference scaling parameters: ", path)
  s <- readRDS(path)
  required <- c("start_VRM", "start_PDBF", "log_start_DistMinorR",
                "end_ELE", "end_VRM", "end_PBUD", "end_PDBF",
                "log_end_DistMainR", "log_end_DistMinorR", "log_end_DistEdgeAbs")
  if (!all(required %in% names(s))) stop("Missing scaling keys: ", paste(setdiff(required, names(s)), collapse=", "))
  for (k in required) {
    if (!all(c("mean", "sd") %in% names(s[[k]]))) stop("Invalid scaling field: ", k)
    if (!is.finite(s[[k]][["mean"]]) || !is.finite(s[[k]][["sd"]]) ||
        s[[k]][["sd"]] <= 0) stop("Invalid scaling moments: ", k)
  }
  s
}

z_with_reference <- function(values, scaling, key) {
  (values - scaling[[key]][["mean"]]) / scaling[[key]][["sd"]]
}

# Extract an environment row for each candidate coordinate (all NA outside grid).
extract_cached_env <- function(cache, xy) {
  if (is.null(dim(xy))) xy <- matrix(xy, ncol=2)
  cells <- terra::cellFromXY(cache$template, xy)
  out <- as.data.frame(matrix(NA_real_, nrow=nrow(xy), ncol=length(cache$values)))
  names(out) <- names(cache$values)
  valid <- which(!is.na(cells) & cells >= 1L & cells <= terra::ncell(cache$template))
  if (length(valid)) {
    for (nm in names(cache$values)) out[[nm]][valid] <- cache$values[[nm]][cells[valid]]
  }
  out
}

make_start_features <- function(env, sc) {
  data.frame(
    z_start_VRM=z_with_reference(env$VRM, sc, "start_VRM"),
    z_start_PDBF=z_with_reference(env$PDBF, sc, "start_PDBF"),
    z_log_start_DistMinorR=z_with_reference(log(pmax(env$DistMinorR, 0.0001)),
                                               sc, "log_start_DistMinorR")
  )
}

make_end_features <- function(env, sc) {
  ele <- z_with_reference(env$ELE, sc, "end_ELE")
  vrm <- z_with_reference(env$VRM, sc, "end_VRM")
  dbf <- z_with_reference(env$PDBF, sc, "end_PDBF")
  data.frame(
    z_end_ELE=ele, z_end_ELE2=ele^2,
    z_end_VRM=vrm, z_end_VRM2=vrm^2,
    z_end_PBUD=z_with_reference(env$PBUD, sc, "end_PBUD"),
    z_end_PDBF=dbf, z_end_PDBF2=dbf^2,
    z_log_end_DistMainR=z_with_reference(log(pmax(env$DistMainR, 0.0001)), sc, "log_end_DistMainR"),
    z_log_end_DistMinorR=z_with_reference(log(pmax(env$DistMinorR, 0.0001)), sc, "log_end_DistMinorR"),
    z_log_end_DistEdgeAbs=z_with_reference(log(pmax(env$DistEdgeAbs, 0.0001)), sc, "log_end_DistEdgeAbs")
  )
}

issf_linear_predictor <- function(df, beta) {
  if (!setequal(names(beta), issf_terms)) stop("Simulation beta must have 17 model terms.")
  # Exact linear predictor used by the final 17-term model.
  x <- cbind(
    sl_=df$sl_, log_sl_=df$log_sl_, cos_ta_=df$cos_ta_,
    `log_sl_:cos_ta_`=df$log_sl_ * df$cos_ta_,
    z_end_ELE=df$z_end_ELE, z_end_ELE2=df$z_end_ELE2,
    z_end_VRM=df$z_end_VRM, z_end_VRM2=df$z_end_VRM2,
    z_end_PBUD=df$z_end_PBUD, z_end_PDBF=df$z_end_PDBF,
    z_end_PDBF2=df$z_end_PDBF2,
    z_log_end_DistMainR=df$z_log_end_DistMainR,
    z_log_end_DistMinorR=df$z_log_end_DistMinorR,
    z_log_end_DistEdgeAbs=df$z_log_end_DistEdgeAbs,
    `log_sl_:z_start_VRM`=df$log_sl_ * df$z_start_VRM,
    `log_sl_:z_start_PDBF`=df$log_sl_ * df$z_start_PDBF,
    `log_sl_:z_log_start_DistMinorR`=df$log_sl_ * df$z_log_start_DistMinorR
  )
  if (!setequal(colnames(x), issf_terms)) stop("Model matrix and term list differ.")
  as.numeric(x[, issf_terms, drop=FALSE] %*% beta[issf_terms])
}

# The initial heading is uniform; each candidate is drawn from observed movement.
simulate_one_track <- function(start_xy, beta, movement, cache, scaling,
                               n_steps, n_candidates=11L, max_attempts=10L,
                               seed=1L, patch_cells=NULL, target_ids=integer(0)) {
  set.seed(as.integer(seed))
  if (!all(is.finite(start_xy)) || length(start_xy) != 2L) stop("Invalid simulation start.")
  if (nrow(movement) < 1L || any(!is.finite(movement$sl_)) ||
      any(!is.finite(movement$ta_)) || any(movement$sl_ <= 0)) stop("Invalid movement pool.")
  stopifnot(n_steps >= 1L, n_candidates >= 1L, max_attempts >= 1L)
  xs <- rep(NA_real_, n_steps + 1L)
  ys <- xs
  patches <- rep(NA_integer_, n_steps + 1L)
  xs[1] <- start_xy[1]; ys[1] <- start_xy[2]
  heading <- runif(1L, -pi, pi)
  completed <- 0L
  initial_env <- extract_cached_env(cache, matrix(start_xy, ncol=2))
  if (!all(is.finite(unlist(initial_env)))) stop("Start point has incomplete environment.")
  if (!is.null(patch_cells)) {
    first_cell <- terra::cellFromXY(cache$template, matrix(start_xy, ncol=2))[1]
    patches[1] <- patch_cells[first_cell]
  }
  for (step_i in seq_len(n_steps)) {
    current <- c(xs[step_i], ys[step_i])
    env_start <- extract_cached_env(cache, matrix(current, ncol=2))
    start_features <- make_start_features(env_start, scaling)
    if (!all(is.finite(unlist(start_features)))) break
    candidates <- NULL
    for (attempt in seq_len(max_attempts)) {
      lengths <- sample(movement$sl_, size=n_candidates, replace=TRUE)
      turns <- sample(movement$ta_, size=n_candidates, replace=TRUE)
      new_heading <- atan2(sin(heading + turns), cos(heading + turns))
      xy <- cbind(current[1] + lengths * cos(new_heading),
                  current[2] + lengths * sin(new_heading))
      features <- make_end_features(extract_cached_env(cache, xy), scaling)
      valid <- stats::complete.cases(features) & lengths > 0
      if (!any(valid)) next
      candidates <- data.frame(
        x=xy[valid, 1], y=xy[valid, 2], sl_=lengths[valid],
        log_sl_=log(lengths[valid]), cos_ta_=cos(turns[valid]),
        heading=new_heading[valid]
      )
      candidates <- cbind(candidates, features[valid, , drop=FALSE])
      for (nm in names(start_features)) candidates[[nm]] <- start_features[[nm]][1]
      break
    }
    if (is.null(candidates) || !nrow(candidates)) break
    eta <- issf_linear_predictor(candidates, beta)
    finite <- which(is.finite(eta))
    if (!length(finite)) break
    weights <- exp(eta[finite] - max(eta[finite]))
    choice <- sample(finite, size=1L, prob=weights)
    xs[step_i + 1L] <- candidates$x[choice]
    ys[step_i + 1L] <- candidates$y[choice]
    heading <- candidates$heading[choice]
    completed <- step_i
    if (!is.null(patch_cells)) {
      chosen_cell <- terra::cellFromXY(cache$template,
                                      matrix(c(xs[step_i + 1L], ys[step_i + 1L]), ncol=2))[1]
      patches[step_i + 1L] <- patch_cells[chosen_cell]
    }
  }
  idx <- seq_len(completed + 1L)
  data.frame(step=seq.int(0L, completed), x=xs[idx], y=ys[idx],
             patch_id=patches[idx])
}

movement_pool_for_group <- function(df, sex, season, excluded_id=NULL) {
  used <- df[df$case_ == 1L & df$Sex == sex & df$Season == season, , drop=FALSE]
  if (!is.null(excluded_id)) used <- used[used$real_id != excluded_id, , drop=FALSE]
  used <- used[is.finite(used$sl_) & used$sl_ > 0 & is.finite(used$ta_), , drop=FALSE]
  if (nrow(used) < 80L) stop("Insufficient movement proposals.")
  used[, c("sl_", "ta_"), drop=FALSE]
}
